/* ---------- rules/Rng.js ---------- */
const Rng = (() => {
/* Rng: the game's seeded random numbers (Part 13).
   Same algorithm as the test scripts (mulberry32), so a seed gives the same numbers everywhere.
   Rng.seeded(seed) returns a function rng() -> number from 0 to 1, like Math.random.
   It also has getState() and setState(n), so a saved game continues the same sequence after loading.
   Rule code only. No screen code. */

class Rng {
  static seeded(seed) {
    let a = seed | 0;
    const rng = function () {
      a = (a + 0x6D2B79F5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
    rng.getState = () => a;
    rng.setState = s => { a = s | 0; };
    return rng;
  }
  /* A seed from the clock, for live games. */
  static randomSeed() { return (Date.now() ^ Math.floor(Math.random() * 4294967296)) | 0; }
  /* True if this rng's place in its sequence can be saved. */
  static canSave(rng) { return typeof rng === "function" && typeof rng.getState === "function" && typeof rng.setState === "function"; }
}
return Rng;
})();

/* ---------- rules/Hearts.js ---------- */
const Hearts = (() => {
/* Hearts: a player's safety pool. Starts at 3, cap 3.
   Only these methods change the count: spend, refill, refund, lose, empty.
   Everything else reads it through .count, .has(n) and .isFull().
   Rule code only. No screen code. Works in the browser and in Node. */

const START = 3, CAP = 3;

class Hearts {
  #n;
  constructor(start = START) { this.#n = Math.max(0, Math.min(CAP, start)); }

  static get START() { return START; }
  static get CAP() { return CAP; }

  get count() { return this.#n; }
  has(n) { return this.#n >= n; }
  isFull() { return this.#n >= CAP; }

  /* Pay n hearts. Refused (returns false, nothing changes) if there are not enough. */
  spend(n) {
    if (n < 0 || this.#n < n) return false;
    this.#n -= n;
    return true;
  }
  /* End of round, and similar small refills: +n, capped. */
  refill(n = 1) { this.#n = Math.min(CAP, this.#n + n); }
  /* Hearts coming back (declined gift, overflow): +n, capped. */
  refund(n) { this.#n = Math.min(CAP, this.#n + n); }
  /* A penalty (Empathy): -n, never below 0. */
  lose(n) { this.#n = Math.max(0, this.#n - n); }
  /* Reboot: set to 0. */
  empty() { this.#n = 0; }
}
return Hearts;
})();

/* ---------- rules/CharacterType.js ---------- */
const CharacterType = (() => {
/* CharacterType: what a work style changes. One base class, three subclasses.
   This is the only place that knows the difference between Cooperative, Independent and Contrarian.
   Other code asks the type (player.type.canSabotage(), player.type.giftCost(2), ...) instead of
   checking its name. Rule code only. No screen code. Works in the browser and in Node. */

const MAX = 10, PEN_MAX = 4;

/* Events that can count toward a second path. */
const PATH_EVENTS = { rescue: "rescue", correctAccusation: "correctAccusation", uncaughtSabotage: "uncaughtSabotage" };

class CharacterType {
  constructor({ key, name, bonus, penalty, pathName, goal, pathEvent }) {
    this.key = key;               // "coop", "indep", "contra": an id for saving and lookups, not for rule checks
    this.name = name;
    this.bonus = bonus;           // the 2 bonus attributes (+2 each at creation)
    this.penalty = penalty;       // the penalty attribute (max 4)
    this.pathName = pathName;     // second path
    this.goal = goal;
    this.pathEvent = pathEvent;   // which event counts toward the second path
  }

  isBonus(k) { return this.bonus.includes(k); }
  max(k) { return k === this.penalty ? PEN_MAX : MAX; }

  /* Gifts. Default: 1 heart per point. */
  giftCost(pts) { return pts; }
  giftRefundPerPoint() { return 1; }
  canAcceptGifts() { return true; }

  canSabotage() { return false; }

  /* Incentives and disincentives. Each type turns on its own. */
  hasEmpathy() { return false; }   // loses 1 heart when a teammate's glitch locks in
  hasCashOut() { return false; }   // once per game, 2 hearts for 1 point, needs full hearts
  hasSkim() { return false; }      // +1 point per uncaught sabotage round, max 2 per game

  /* True if this event counts toward this type's second path. */
  pathCounts(event) { return event === this.pathEvent; }

  static get MAX() { return MAX; }
  static get PEN_MAX() { return PEN_MAX; }
  static get PATH_EVENTS() { return PATH_EVENTS; }
  /* Look up a type by key. Passing a type object returns it unchanged. */
  static get(key) {
    if (key instanceof CharacterType) return key;
    const t = ALL[key];
    if (!t) throw new Error("Unknown type: " + key);
    return t;
  }
  static all() { return Object.values(ALL); }
}

class Cooperative extends CharacterType {
  constructor() {
    super({ key: "coop", name: "Cooperative", bonus: ["collab", "composure"], penalty: "initiative",
            pathName: "Lifeline", goal: 1, pathEvent: PATH_EVENTS.rescue });
  }
  hasEmpathy() { return true; }
}

class Independent extends CharacterType {
  constructor() {
    super({ key: "indep", name: "Independent", bonus: ["focus", "grit"], penalty: "collab",
            pathName: "Auditor", goal: 1, pathEvent: PATH_EVENTS.correctAccusation });
  }
  giftCost(pts) { return pts === 1 ? 2 : 3; }   // 1 point costs 2, 2 points cost 3
  giftRefundPerPoint() { return 2; }
  canAcceptGifts() { return false; }
  hasCashOut() { return true; }
}

class Contrarian extends CharacterType {
  constructor() {
    super({ key: "contra", name: "Contrarian", bonus: ["initiative", "grit"], penalty: "composure",
            pathName: "Exploit", goal: 3, pathEvent: PATH_EVENTS.uncaughtSabotage });
  }
  canSabotage() { return true; }
  hasSkim() { return true; }
}

// One shared object per type. Types hold no player state, so players can share them.
const ALL = { coop: new Cooperative(), indep: new Independent(), contra: new Contrarian() };

CharacterType.Cooperative = Cooperative;
CharacterType.Independent = Independent;
CharacterType.Contrarian = Contrarian;
return CharacterType;
})();

/* ---------- rules/Wallet.js ---------- */
const Wallet = (() => {
/* Wallet: a player's earned points, placement draft, Skim and Cash Out (Step 5).
   Changes the player's stats only through Player methods (attr, addAttr, max).
   Rule code only. No screen code. */

const KEYS = ["focus", "initiative", "collab", "composure", "grit"];
const SKIM_MAX = 2, CASHOUT_USES = 1, CASHOUT_COST = 2;

class Wallet {
  #player;
  #earned = 0;
  #draft = {};
  #placedThisRound = 0;
  #skimUsed = 0;
  #cashOutUsed = 0;
  #cashedOutThisRound = false;

  constructor(player) { this.#player = player; }

  get earned() { return this.#earned; }
  set earned(n) { this.#earned = n; }
  get draft() { return this.#draft; }
  get placedThisRound() { return this.#placedThisRound; }
  get skimUsed() { return this.#skimUsed; }
  get cashOutUsed() { return this.#cashOutUsed; }
  get cashedOutThisRound() { return this.#cashedOutThisRound; }

  resetRound() {
    this.#earned = 0;
    this.#cashedOutThisRound = false;
    this.#draft = {};
    this.#placedThisRound = 0;
  }

  /* Cash Out (Independent): once per game, needs full hearts, 2 hearts for 1 point. */
  canCashOut() {
    const p = this.#player;
    return p.type.hasCashOut() && !p.isStuck() && this.#cashOutUsed < CASHOUT_USES &&
           p.hearts.isFull() && p.hearts.has(CASHOUT_COST);
  }
  cashOut() {
    if (!this.canCashOut()) return false;
    this.#player.hearts.spend(CASHOUT_COST);
    this.#cashOutUsed += 1;
    this.#cashedOutThisRound = true;
    this.#earned += 1;
    return true;
  }

  /* Skim (Contrarian): +1 per uncaught sabotage round, max 2 per game. */
  takeSkim() {
    const p = this.#player;
    if (!p.type.hasSkim() || p.sabotagesThisRound === 0 || p.caughtThisRound) return 0;
    if (this.#skimUsed >= SKIM_MAX) return 0;
    this.#skimUsed += 1;
    return 1;
  }

  /* Place earned points. alloc = { focus: n, ... }. Must use all points and respect max. */
  placePoints(alloc) {
    const p = this.#player;
    const n = KEYS.reduce((s, k) => s + (alloc[k] || 0), 0);
    if (n !== this.#earned) throw new Error("Place exactly " + this.#earned + " points");
    for (const k of KEYS) {
      if ((alloc[k] || 0) < 0) throw new Error("No negative placement");
      if (p.attr(k) + (alloc[k] || 0) > p.max(k)) throw new Error(k + " would pass its max");
    }
    for (const k of KEYS) p.addAttr(k, alloc[k] || 0);
    this.#earned = 0;
    this.#draft = {};
    this.#placedThisRound = n;
  }
  placeLeft(place) { return this.#earned - KEYS.reduce((s, k) => s + (place[k] || 0), 0); }
  canPlace(place, k) { return this.placeLeft(place) > 0 && this.#player.attr(k) + (place[k] || 0) < this.#player.max(k); }
  canUnplace(place, k) { return (place[k] || 0) > 0; }
  coversFromPoints(k, cost) { return this.#player.attr(k) >= cost; }
  roomLeft() { return KEYS.reduce((s, k) => s + (this.#player.max(k) - this.#player.attr(k)), 0); }

  toJSON() {
    return {
      earned: this.#earned,
      draft: { ...this.#draft },
      placedThisRound: this.#placedThisRound,
      skimUsed: this.#skimUsed,
      cashOutUsed: this.#cashOutUsed,
      cashedOutThisRound: this.#cashedOutThisRound,
    };
  }
  static fromJSON(player, data) {
    const w = new Wallet(player);
    w.#earned = data.earned || 0;
    w.#draft = data.draft ? { ...data.draft } : {};
    w.#placedThisRound = data.placedThisRound || 0;
    w.#skimUsed = data.skimUsed || 0;
    w.#cashOutUsed = data.cashOutUsed || 0;
    w.#cashedOutThisRound = !!data.cashedOutThisRound;
    return w;
  }
}

Wallet.SKIM_MAX = SKIM_MAX;
Wallet.CASHOUT_COST = CASHOUT_COST;
return Wallet;
})();

/* ---------- rules/PlayerStatus.js ---------- */
const PlayerStatus = (() => {
/* PlayerStatus: glitches, idle, pending attendance glitch, and status flags (Step 6).
   Only reads stats and hearts through Player; never changes them.
   Rule code only. No screen code. */

const KEYS = ["focus", "initiative", "collab", "composure", "grit"];
const AT_RISK_COST = 3;
const STUCK_AT = 2;

class PlayerStatus {
  #player;
  #glitches = 0;
  #idle = false;
  #attendancePending = false;

  constructor(player) { this.#player = player; }

  get glitches() { return this.#glitches; }
  set glitches(n) { this.#glitches = n; }
  get idle() { return this.#idle; }
  set idle(v) { this.#idle = !!v; }
  get attendancePending() { return this.#attendancePending; }
  set attendancePending(v) { this.#attendancePending = !!v; }

  addGlitch() { this.#glitches += 1; }
  isStuck() { return this.#glitches >= STUCK_AT; }
  isActive() { return !this.isStuck() && !this.#idle; }
  isGlitching() { return KEYS.some(k => this.#player.attr(k) < 0); }
  isGlitchingAny() { return this.isGlitching() || this.#attendancePending; }
  isAtRisk() {
    return KEYS.some(k => this.#player.attr(k) + Math.floor(this.#player.hearts.count / this.#player.rate(k)) < AT_RISK_COST);
  }

  /* What other players see. Never numbers. */
  flag() {
    if (this.isStuck()) return "Stuck";
    if (this.isGlitchingAny()) return "Glitching";
    if (this.isAtRisk()) return "At risk";
    return "OK";
  }
  /* Progress board status. First that applies: Stuck, Glitching, Idle, At risk, Active. */
  boardStatus() {
    if (this.isStuck()) return "Stuck";
    if (this.isGlitchingAny()) return "Glitching";
    if (this.#idle) return "Idle";
    if (this.isAtRisk()) return "At risk";
    return "Active";
  }

  toJSON() {
    return { glitches: this.#glitches, idle: this.#idle, attendancePending: this.#attendancePending };
  }
  static fromJSON(player, data) {
    const s = new PlayerStatus(player);
    s.#glitches = data.glitches || 0;
    s.#idle = !!data.idle;
    s.#attendancePending = !!data.attendancePending;
    return s;
  }
}

PlayerStatus.AT_RISK_COST = AT_RISK_COST;
PlayerStatus.STUCK_AT = STUCK_AT;
return PlayerStatus;
})();

/* ---------- rules/Attributes.js ---------- */
const Attributes = (() => {
/* Attributes: a player's 5 stats, ability rolls, trial costs, losses, gifts, and stat reboot (Step 10).
   Never touches hearts or type directly; reads/changes them only through Player.
   Rule code only. No screen code. */

const KEYS = ["focus", "initiative", "collab", "composure", "grit"];
const TIE_ORDER = ["focus", "collab", "initiative", "grit", "composure"];   // the usual tie order
const GIFT_TIE_ORDER = TIE_ORDER;

const START_EACH = 1;      // every attribute starts at 1
const SPEND = 15;          // points the player spends at creation
const BOOST = 2;           // type boost per bonus attribute

/* Stat abilities (Part 4b). per = chance per stat point. */
const ABILITY = {
  focus:      { name: "Focus",         per: 0.10, what: "safe accusation" },
  collab:     { name: "Collaboration", per: 0.10, what: "gift costs 1 heart less (min 1)" },
  initiative: { name: "Initiative",    per: 0,    what: "vote points (applies in Levels 5 and 6)" },
  grit:       { name: "Grit",          per: 0.05, what: "extra heart at round end" },
  composure:  { name: "Composure",     per: 0.10, what: "sabotage drains only 1" },
};

class Attributes {
  #player;
  #attrs = {};

  constructor(player, spend) {
    this.#player = player;
    if (spend === null) return;
    let total = 0;
    for (const k of KEYS) {
      const s = spend[k] || 0;
      if (s < 0) throw new Error("Spend cannot be negative");
      total += s;
      this.#attrs[k] = START_EACH + s + (player.isBonus(k) ? BOOST : 0);
      if (this.#attrs[k] > player.max(k)) throw new Error(k + " is over its max");
    }
    if (total !== SPEND) throw new Error("Must spend exactly " + SPEND + " points");
  }

  get attrs() { return { ...this.#attrs }; }
  setAttrsForTest(values) { this.#attrs = { ...this.#attrs, ...values }; }

  rate(k) { return this.#player.isBonus(k) ? 1 : 2; }   // hearts per point covered
  attr(k) { return this.#attrs[k]; }
  addAttr(k, delta) { this.#attrs[k] += delta; }

  total() { return KEYS.reduce((s, k) => s + this.#attrs[k], 0); }
  lowest() { return Math.min(...KEYS.map(k => this.#attrs[k])); }
  highestKey() { return KEYS.reduce((m, k) => (this.#attrs[k] > this.#attrs[m] ? k : m), KEYS[0]); }
  lowestKey() { return KEYS.reduce((m, k) => (this.#attrs[k] < this.#attrs[m] ? k : m), KEYS[0]); }
  /* Highest attribute; ties go to the first in the given order. */
  highestKeyIn(order) { return order.reduce((m, k) => (this.#attrs[k] > this.#attrs[m] ? k : m), order[0]); }

  /* Stat abilities (Part 4b). The stat's value right now: negative counts as 0, max 10. */
  abilityValue(k) { return Math.max(0, Math.min(10, this.#attrs[k])); }
  /* Chance (0 to 1) for the chance-based abilities. */
  abilityChance(k) { return this.abilityValue(k) * ABILITY[k].per; }
  /* Vote weight from Initiative: 1 + Initiative / 10. */
  voteWeight() { return 1 + this.abilityValue("initiative") / 10; }
  /* True if a chance ability fires. rng is the game's seeded rng. */
  rollAbility(k, rng) {
    if (typeof rng !== "function") throw new Error("rollAbility needs the game's seeded rng.");
    return rng() < this.abilityChance(k);
  }
  /* Lines for this player's own screen only. Never show them for other players. */
  abilityLines() {
    return KEYS.map(k => {
      const v = this.abilityValue(k), a = ABILITY[k];
      const amount = k === "initiative" ? "x" + this.voteWeight().toFixed(1) : Math.round(v * a.per * 100) + "%";
      return { key: k, value: v, text: a.name + " " + v + ": " + amount + " " + a.what };
    });
  }

  /* Lose points from one attribute, from any cause. Hearts cover any shortfall below 0. */
  lose(k, n) {
    this.#attrs[k] -= n;
    this.cover(k);
  }

  cover(k) {
    if (this.#attrs[k] >= 0) return 0;
    const short = -this.#attrs[k];
    const r = this.rate(k);
    const covered = Math.min(short, Math.floor(this.#player.heartCount() / r));
    this.#player.spendHearts(covered * r);
    this.#attrs[k] += covered;
    return covered * r;   // hearts used
  }

  /* Trial cost. Glitching players pay too. Stuck players do not. */
  payTrial(k, cost) {
    if (this.#player.isStuck()) return null;
    const before = this.#attrs[k], heartsBefore = this.#player.heartCount();
    this.lose(k, cost);
    return { attr: k, before, after: this.#attrs[k], heartsUsed: heartsBefore - this.#player.heartCount() };
  }

  /* Wrong accusation penalty. Ties: Focus, Collaboration, Initiative, Grit, Composure. */
  takeFromHighest(n) {
    for (let i = 0; i < n; i++) this.lose(this.highestKeyIn(TIE_ORDER), 1);
  }

  /* Where a gift point goes. Glitching: the glitching attribute (lowest first if two are below 0).
     Not glitching: the lowest attribute that still has room below its max.
     Ties: Focus, Collaboration, Initiative, Grit, Composure. The receiver does not pick.
     Returns null if every attribute is at its max. */
  giftTarget() {
    const p = this.#player;
    const pool = p.isGlitching() ? KEYS.filter(k => this.#attrs[k] < 0)
                                 : KEYS.filter(k => this.#attrs[k] < p.max(k));
    const order = GIFT_TIE_ORDER.filter(k => pool.includes(k));
    if (!order.length) return null;
    return order.reduce((m, k) => (this.#attrs[k] < this.#attrs[m] ? k : m));
  }

  /* Points past 0 stay in that attribute. If it fills up, the next point goes to the
     lowest attribute that still has room. Returns points with nowhere to go (overflow, refunded). */
  receiveGift(pts) {
    const p = this.#player;
    let target = this.giftTarget();
    let overflow = 0;
    for (let i = 0; i < pts; i++) {
      if (p.isGlitching() || target === null || this.#attrs[target] >= p.max(target)) target = this.giftTarget();
      if (target !== null && this.#attrs[target] < p.max(target)) this.#attrs[target] += 1;
      else overflow += 1;
    }
    return overflow;
  }

  /* Take points evenly from the other attributes until the glitched one reaches 1.
     Any shortfall the others cannot cover is forgiven: it still ends at 1.
     Hearts are emptied by Player.reboot(). */
  reboot() {
    for (const k of KEYS) {
      if (this.#attrs[k] >= 0) continue;
      const need = 1 - this.#attrs[k];
      let got = 0;
      while (got < need) {
        const donors = KEYS.filter(d => d !== k && this.#attrs[d] > 0)
                           .sort((a, b) => this.#attrs[b] - this.#attrs[a]);
        if (!donors.length) break;
        for (const d of donors) {
          if (got >= need) break;
          this.#attrs[d] -= 1; got += 1;
        }
      }
      this.#attrs[k] = 1;   // always reboots to 1, shortfall forgiven
    }
  }

  toJSON() { return { ...this.#attrs }; }
  static fromJSON(player, data) {
    const a = new Attributes(player, null);
    a.#attrs = data.attrs ? { ...data.attrs } : {};
    return a;
  }
}

Attributes.KEYS = KEYS;
Attributes.TIE_ORDER = TIE_ORDER;
Attributes.START_EACH = START_EACH;
Attributes.SPEND = SPEND;
Attributes.BOOST = BOOST;
Attributes.ABILITY = ABILITY;
return Attributes;
})();

/* ---------- rules/PathTracker.js ---------- */
const PathTracker = (() => {
/* PathTracker: second path progress, graduation checks, and locked ending (Step 10).
   Rule code only. No screen code. */

const GRAD_TOTAL = 24, GRAD_MIN = 2;

class PathTracker {
  #player;
  #pathProgress = 0;
  #pathDone = false;
  #locked = null;   // { ending, wins }, set once by Game.results()

  constructor(player) { this.#player = player; }

  get pathProgress() { return this.#pathProgress; }
  get pathDone() { return this.#pathDone; }
  set pathDone(v) { this.#pathDone = !!v; }
  get locked() { return this.#locked; }

  /* An event happened (rescue, correctAccusation, uncaughtSabotage). It counts only if it is
     this type's second-path event. Returns true if it counted. */
  creditPath(event) {
    const t = this.#player.type;
    if (!t.pathCounts(event) || this.#pathDone) return false;
    this.#pathProgress += 1;
    if (this.#pathProgress >= t.goal) this.#pathDone = true;
    return true;
  }

  /* The three graduation checks, for the Stats Update screen. */
  gradChecks() {
    const p = this.#player;
    const total = p.total(), lowest = p.lowest();
    return { total, totalOk: total >= GRAD_TOTAL, lowest, lowestOk: lowest >= GRAD_MIN,
             glitches: p.glitches, glitchesOk: !p.isStuck() };
  }
  graduates() {
    const p = this.#player;
    return !p.isStuck() && p.total() >= GRAD_TOTAL && p.lowest() >= GRAD_MIN;
  }
  /* After Game.results() the ending is locked: wins() and ending() return the locked values. */
  lockEnding() {
    if (this.#locked) return;
    const ending = this.ending(), wins = this.wins();
    this.#locked = Object.freeze({ ending, wins });
  }
  /* Idle at Graduation (when results() runs): Contract renewed, even if the stats would graduate.
     A second path already completed still wins. */
  wins() {
    if (this.#locked) return this.#locked.wins;
    return (this.graduates() && !this.#player.idle) || this.#pathDone;
  }
  ending() {
    if (this.#locked) return this.#locked.ending;
    if (this.graduates() && !this.#player.idle) return "Graduated";
    if (this.#pathDone) return this.#player.type.pathName + " complete";
    return "Contract renewed";
  }

  toJSON() {
    return {
      pathProgress: this.#pathProgress,
      pathDone: this.#pathDone,
      locked: this.#locked ? { ...this.#locked } : null,
    };
  }
  static fromJSON(player, data) {
    const pt = new PathTracker(player);
    pt.#pathProgress = data.pathProgress || 0;
    pt.#pathDone = !!data.pathDone;
    pt.#locked = data.locked ? Object.freeze({ ...data.locked }) : null;
    return pt;
  }
}

PathTracker.GRAD_TOTAL = GRAD_TOTAL;
PathTracker.GRAD_MIN = GRAD_MIN;
return PathTracker;
})();

/* ---------- rules/Player.js ---------- */
const Player = (() => {
/* Player: one intern. Coordinates type, hearts, attributes, status, second path, and wallet.
   Rule code only. No screen code. Works in the browser and in Node. */


const KEYS = Attributes.KEYS;
const TIE_ORDER = Attributes.TIE_ORDER;
const START_EACH = Attributes.START_EACH;
const SPEND = Attributes.SPEND;
const BOOST = Attributes.BOOST;
const ABILITY = Attributes.ABILITY;
const AT_RISK_COST = PlayerStatus.AT_RISK_COST;
const STUCK_AT = PlayerStatus.STUCK_AT;
const GRAD_TOTAL = PathTracker.GRAD_TOTAL;
const GRAD_MIN = PathTracker.GRAD_MIN;
const SKIM_MAX = Wallet.SKIM_MAX, CASHOUT_COST = Wallet.CASHOUT_COST;
const STATUS_KEYS = ["glitches", "idle", "attendancePending"];
const PATH_KEYS = ["pathProgress", "pathDone", "locked"];
const WALLET_KEYS = ["earned", "draft", "placedThisRound", "skimUsed", "cashOutUsed", "cashedOutThisRound"];
const PART_KEYS = ["attrs", ...STATUS_KEYS, ...PATH_KEYS, ...WALLET_KEYS];
const FROM_JSON = Symbol();

class Player {
  #attributes;
  #status;
  #pathTracker;
  #wallet;

  /* type: a key ("coop", "indep", "contra") or a CharacterType.
     spend: { focus: n, ... } adding up to 15. Boost is added here. */
  constructor(opts) {
    if (opts === FROM_JSON) return;
    const { id, name, type, spend, isBot = false } = opts;
    this.id = id;
    this.name = name;
    this.type = CharacterType.get(type);
    this.isBot = isBot;
    this.teamId = null;

    this.#attributes = new Attributes(this, spend);
    this.hearts = new Hearts();
    this.#status = new PlayerStatus(this);
    this.lastActivity = null;   // time of the last key, click or touch (read by the Attendance check, Part 7)
    this.attendanceMissAt = null;   // time of the last missed Attendance check (restarts the timer)
    this.attendancePopupAt = null;  // time the "Still there?" popup opened; null when closed
    this.attendancePaused = false;  // true on screens with no input (intro, briefings, intermissions)
    this.attendanceResumeAt = null; // time the timer last resumed (starts a fresh clock)

    this.#pathTracker = new PathTracker(this);

    // Contrarian
    this.caughtBy = [];   // ids of teams that caught this player sabotaging
    this.#wallet = new Wallet(this);

    this.resetRoundFlags();
  }

  static get KEYS() { return KEYS; }
  static get SPEND() { return SPEND; }
  static get START_EACH() { return START_EACH; }
  static get BOOST() { return BOOST; }

  /* Character creation draft, before the Player exists. spend = { focus: n, ... } points added (0 or more). */
  static spendLeft(spend) { return SPEND - KEYS.reduce((s, k) => s + (spend[k] || 0), 0); }
  /* Starting value with the type boost. */
  static startValue(type, spend, k) {
    return START_EACH + (spend[k] || 0) + (CharacterType.get(type).isBonus(k) ? BOOST : 0);
  }
  static canRaise(type, spend, k) {
    return Player.spendLeft(spend) > 0 && Player.startValue(type, spend, k) < CharacterType.get(type).max(k);
  }
  static canLower(spend, k) { return (spend[k] || 0) > 0; }

  isBonus(k) { return this.type.isBonus(k); }
  max(k) { return this.type.max(k); }
  heartCount() { return this.hearts.count; }
  spendHearts(n) { return this.hearts.spend(n); }

  get attrs() { return this.#attributes.attrs; }
  setAttrsForTest(values) { this.#attributes.setAttrsForTest(values); }
  rate(k) { return this.#attributes.rate(k); }
  attr(k) { return this.#attributes.attr(k); }
  addAttr(k, delta) { this.#attributes.addAttr(k, delta); }

  total() { return this.#attributes.total(); }
  lowest() { return this.#attributes.lowest(); }
  highestKey() { return this.#attributes.highestKey(); }
  lowestKey() { return this.#attributes.lowestKey(); }
  highestKeyIn(order) { return this.#attributes.highestKeyIn(order); }

  get glitches() { return this.#status.glitches; }
  set glitches(n) { this.#status.glitches = n; }
  get idle() { return this.#status.idle; }
  set idle(v) { this.#status.idle = v; }
  get attendancePending() { return this.#status.attendancePending; }
  set attendancePending(v) { this.#status.attendancePending = v; }

  isStuck() { return this.#status.isStuck(); }
  isActive() { return this.#status.isActive(); }
  /* Any input (including typing a submission) counts as activity and resets the Attendance check. */
  markActive(now = Date.now()) { this.lastActivity = now; }
  isGlitching() { return this.#status.isGlitching(); }
  isGlitchingAny() { return this.#status.isGlitchingAny(); }
  isAtRisk() { return this.#status.isAtRisk(); }
  flag() { return this.#status.flag(); }
  boardStatus() { return this.#status.boardStatus(); }

  abilityValue(k) { return this.#attributes.abilityValue(k); }
  abilityChance(k) { return this.#attributes.abilityChance(k); }
  voteWeight() { return this.#attributes.voteWeight(); }
  rollAbility(k, rng) { return this.#attributes.rollAbility(k, rng); }
  abilityLines() { return this.#attributes.abilityLines(); }

  /* Caught by this team: no sabotage while on it. Switching teams allows sabotage again. */
  wasCaughtBy(teamId) { return this.caughtBy.includes(teamId); }
  /* Caught: costs no points. No sabotage on any team next round (see resetRoundFlags),
     then no sabotage while on a team that caught them. Exploit is never lost. */
  markCaughtBy(teamId) {
    this.caughtThisRound = true;
    if (!this.wasCaughtBy(teamId)) this.caughtBy.push(teamId);
  }

  resetRoundFlags() {
    // Caught last round: no sabotage on any team this round.
    this.sabotageBlockedThisRound = !!this.caughtThisRound;
    this.sabotagesThisRound = 0;
    this.caughtThisRound = false;
    this.wasSabotagedThisRound = false;
    this.accusedThisRound = false;
    this.correctAccusation = false;
    this.glitchedThisRound = false;
    this.attendanceMissesThisRound = 0;      // counted misses (max 1 per round); a miss saved by a gift still counts
    this.#status.attendancePending = false;  // missed check-in, not yet locked: Glitching until a gift saves it or it locks in
    this.attendanceGlitchThisRound = false;  // this round's locked glitch came only from a missed check-in
    this.#wallet.resetRound();
  }

  /* Save (Part 13): plain data only. type is saved as its key, hearts as the count. */
  toJSON() {
    const out = {};
    for (const [k, v] of Object.entries(this)) {
      if (k === "type") out.type = v.key;
      else if (k === "hearts") { out.hearts = v.count; out.glitches = this.#status.glitches; out.idle = this.#status.idle; }
      else {
        out[k] = v === undefined ? null : JSON.parse(JSON.stringify(v));
        if (k === "teamId") out.attrs = this.#attributes.toJSON();
        else if (k === "attendanceResumeAt") Object.assign(out, this.#pathTracker.toJSON());
        else if (k === "caughtBy") Object.assign(out, this.#wallet.toJSON());
        else if (k === "attendanceMissesThisRound") out.attendancePending = this.#status.attendancePending;
      }
    }
    return out;
  }
  /* Load: rebuild a Player from toJSON() data, without re-running character creation. */
  static fromJSON(data) {
    const p = new Player(FROM_JSON);
    for (const [k, v] of Object.entries(data)) {
      if (PART_KEYS.includes(k)) continue;
      p[k] = v === null || typeof v !== "object" ? v : JSON.parse(JSON.stringify(v));
    }
    p.type = CharacterType.get(data.type);
    p.hearts = new Hearts(data.hearts);
    p.#attributes = Attributes.fromJSON(p, data);
    p.#status = PlayerStatus.fromJSON(p, data);
    p.#pathTracker = PathTracker.fromJSON(p, data);
    p.#wallet = Wallet.fromJSON(p, data);
    return p;
  }

  lose(k, n) { this.#attributes.lose(k, n); }
  cover(k) { return this.#attributes.cover(k); }
  payTrial(k, cost) { return this.#attributes.payTrial(k, cost); }
  takeFromHighest(n) { this.#attributes.takeFromHighest(n); }
  giftTarget() { return this.#attributes.giftTarget(); }
  receiveGift(pts) { return this.#attributes.receiveGift(pts); }

  /* Lock-in: if still below 0, or a missed check-in is still pending, the glitch counts. Reboot.
     An attribute glitch and an attendance glitch in the same round count as one glitch.
     Returns true if a glitch locked in. */
  lockIn() {
    if (this.isStuck() || !this.isGlitchingAny()) return false;
    if (this.glitchedThisRound && !this.isGlitching()) { this.#status.attendancePending = false; return false; }   // counts as one
    if (!this.isGlitching()) this.attendanceGlitchThisRound = true;   // attendance only
    this.#status.attendancePending = false;
    this.#status.addGlitch();
    this.glitchedThisRound = true;
    this.reboot();
    return true;
  }

  /* A missed check-in after the gift window closed locks in at once, with the same reboot
     (hearts to 0; no attribute refill, because no attribute is below 0).
     If a glitch already locked in this round, they count as one: nothing more happens.
     Returns true if a glitch locked in. */
  lockAttendanceGlitch() {
    if (this.isStuck() || this.glitchedThisRound) return false;
    this.attendancePending = true;
    return this.lockIn();
  }

  /* Reboot: reset any glitched attributes to 1 (donors cover evenly), then empty hearts. */
  reboot() {
    this.#attributes.reboot();
    this.hearts.empty();
  }

  get earned() { return this.#wallet.earned; }
  set earned(n) { this.#wallet.earned = n; }
  get draft() { return this.#wallet.draft; }
  get placedThisRound() { return this.#wallet.placedThisRound; }
  get skimUsed() { return this.#wallet.skimUsed; }
  get cashOutUsed() { return this.#wallet.cashOutUsed; }
  get cashedOutThisRound() { return this.#wallet.cashedOutThisRound; }

  canCashOut() { return this.#wallet.canCashOut(); }
  cashOut() { return this.#wallet.cashOut(); }
  takeSkim() { return this.#wallet.takeSkim(); }
  placePoints(alloc) { this.#wallet.placePoints(alloc); }
  placeLeft(place) { return this.#wallet.placeLeft(place); }
  canPlace(place, k) { return this.#wallet.canPlace(place, k); }
  canUnplace(place, k) { return this.#wallet.canUnplace(place, k); }
  coversFromPoints(k, cost) { return this.#wallet.coversFromPoints(k, cost); }
  roomLeft() { return this.#wallet.roomLeft(); }

  get pathProgress() { return this.#pathTracker.pathProgress; }
  get pathDone() { return this.#pathTracker.pathDone; }
  set pathDone(v) { this.#pathTracker.pathDone = v; }
  get locked() { return this.#pathTracker.locked; }

  creditPath(event) { return this.#pathTracker.creditPath(event); }
  gradChecks() { return this.#pathTracker.gradChecks(); }
  graduates() { return this.#pathTracker.graduates(); }
  lockEnding() { this.#pathTracker.lockEnding(); }
  wins() { return this.#pathTracker.wins(); }
  ending() { return this.#pathTracker.ending(); }
}

Player.ABILITY = ABILITY;
Player.TIE_ORDER = TIE_ORDER;
Player.AT_RISK_COST = AT_RISK_COST;
Player.STUCK_AT = STUCK_AT;
Player.GRAD_TOTAL = GRAD_TOTAL;
Player.GRAD_MIN = GRAD_MIN;
Player.SKIM_MAX = SKIM_MAX;
Player.CASHOUT_COST = CASHOUT_COST;
return Player;
})();

/* ---------- rules/Team.js ---------- */
const Team = (() => {
/* Team: members and the trial result for the round. */

class Team {
  constructor({ id, name, members = [] }) {
    this.id = id;
    this.name = name;
    this.members = [];
    this.won = null;   // trial result this round: true, false, or null (not set)
    this.trialWins = 0;   // trials won so far this game (Progress board)
    members.forEach(p => this.add(p));
  }
  add(p) { p.teamId = this.id; this.members.push(p); }
  remove(p) { this.members = this.members.filter(q => q !== p); }
  size() { return this.members.length; }
  active() { return this.members.filter(p => p.isActive()); }   // not Stuck, not idle
  mates(p) { return this.members.filter(q => q !== p); }
  has(p) { return this.members.includes(p); }
  resetRound() { this.won = null; }

  /* Save (Part 13): members by player id. */
  toJSON() { return { id: this.id, name: this.name, members: this.members.map(p => p.id), won: this.won, trialWins: this.trialWins }; }
  /* Load. byId: player id -> Player. Members keep their saved order. */
  static fromJSON(data, byId) {
    const t = new Team({ id: data.id, name: data.name, members: data.members.map(id => byId.get(id)) });
    t.won = data.won;
    t.trialWins = data.trialWins;
    return t;
  }
}

Team.MIN = 3;   // team switching keeps every team at 3 to 5 members
Team.MAX = 5;
return Team;
})();

/* ---------- rules/Sabotage.js ---------- */
const Sabotage = (() => {
/* Sabotage: Contrarian only, teammates only, costs hearts, drains the trial attribute. */

class Sabotage {
  /* 1 heart for the first in a round, 2 for each extra in the same round. */
  static cost(actor) { return actor.sabotagesThisRound === 0 ? 1 : 2; }

  /* 2 points. Composure x 10% chance it is only 1 (Part 4b). */
  static drain(target, rng) { return target.rollAbility("composure", rng) ? 1 : 2; }

  /* Returns null if allowed, or a reason string if not. */
  static check(actor, target, team) {
    if (!actor.type.canSabotage()) return "Only Contrarians can sabotage.";
    if (actor.isStuck()) return "You are Stuck.";
    if (actor.idle) return "You are idle.";
    if (actor.sabotageBlockedThisRound) return "You were caught last round. No sabotage on any team this round.";
    if (actor.wasCaughtBy(team.id)) return "This team caught you. No sabotage while you are on it.";
    if (target === actor) return "You cannot sabotage yourself.";
    if (!team.has(target)) return "Teammates only.";
    if (target.isStuck()) return "Stuck players cannot be sabotaged.";
    if (!actor.hearts.has(Sabotage.cost(actor))) return "Not enough hearts.";
    return null;
  }

  /* Apply it. The victim is told privately (victimNotice). */
  static apply(round, actor, target, team, rng) {
    const why = Sabotage.check(actor, target, team);
    if (why) return { ok: false, reason: why };
    const cost = Sabotage.cost(actor);
    actor.hearts.spend(cost);
    actor.sabotagesThisRound += 1;
    const drain = Sabotage.drain(target, rng);
    target.lose(round.attr, drain);   // hearts cover a drain below 0
    target.wasSabotagedThisRound = true;
    const rec = { actor, target, drain, cost };
    round.sabotages.push(rec);
    return { ok: true, ...rec, victimNotice: "Someone drained " + drain + " from your " + round.attr + "." };
  }
}
return Sabotage;
})();

/* ---------- rules/Accusation.js ---------- */
const Accusation = (() => {
/* Accusation: one per player per round, against a teammate. Every type can accuse. */


class Accusation {
  static check(accuser, target, team) {
    if (accuser.isStuck()) return "You are Stuck.";
    if (accuser.idle) return "You are idle.";
    if (accuser.accusedThisRound) return "One accusation per round.";
    if (target === accuser) return "You cannot accuse yourself.";
    if (!team.has(target)) return "Teammates only.";
    return null;
  }

  /* Correct = the target sabotaged this round.
     Correct: +1 at Stats Update, Auditor credit, target is caught by this team
     (loses 0 points; no sabotage on any team next round; this round's sabotage does not count toward Exploit or Skim;
     no sabotage while on this team; Exploit is never lost).
     Wrong: accuser loses 1 from highest attribute (can cause a glitch),
     unless Focus saves it (Focus x 10% chance to cost nothing). */
  static apply(round, accuser, target, team, rng) {
    const why = Accusation.check(accuser, target, team);
    if (why) return { ok: false, reason: why };
    accuser.accusedThisRound = true;
    const correct = target.sabotagesThisRound > 0;
    if (correct) {
      accuser.correctAccusation = true;
      accuser.creditPath(CharacterType.PATH_EVENTS.correctAccusation);   // Auditor
      target.markCaughtBy(team.id);
    }
    // Wrong: Focus x 10% chance it costs nothing (Part 4b).
    const safe = !correct && accuser.rollAbility("focus", rng);
    if (!correct && !safe) accuser.takeFromHighest(1);
    const rec = { accuser, target, correct, safe };
    round.accusations.push(rec);
    return { ok: true, ...rec };
  }
}
return Accusation;
})();

/* ---------- rules/Gift.js ---------- */
const Gift = (() => {
/* Gift: sent to any teammate during Open Floor or the gift window, whatever their status
   (Stuck players cannot give or receive). The receiver answers Accept or Decline.
   Accept: points go to the glitching attribute if the receiver is Glitching, else to their lowest
   attribute that still has room (ties: Focus, Collaboration, Initiative, Grit, Composure).
   Decline, or no answer by the end of the step: the giver gets the hearts back.
   Independents refuse automatically. The receiver does not pick the attribute.
   Idle players (Part 8) cannot give or answer gifts. Gifts sent to them stay pending and expire
   (refunded) at the end of the step, unless they come back and answer in time. */


class Gift {
  /* Heart cost. Independent: 1 point costs 2, 2 points cost 3. Others: 1 per point. */
  static cost(giver, pts) { return giver.type.giftCost(pts); }
  /* Hearts refunded per point that cannot land (overflow). */
  static refundPerPoint(giver) { return giver.type.giftRefundPerPoint(); }

  static check(giver, receiver, team, pts) {
    if (pts !== 1 && pts !== 2) return "Gift 1 or 2 points.";
    if (giver.isStuck()) return "You are Stuck.";
    if (giver.idle) return "You are idle.";
    if (giver === receiver) return "You cannot gift yourself.";
    if (!team.has(receiver)) return "Teammates only.";
    if (receiver.isStuck()) return "Stuck players cannot receive gifts.";
    if (!giver.hearts.has(Gift.cost(giver, pts))) return "Not enough hearts.";
    return null;
  }

  /* Send a gift. The giver pays now. The gift waits for the receiver's answer (status "pending").
     Independents refuse at once and nothing is spent (status "refused").
     The result's .gift is the record to pass to accept or decline. */
  static apply(round, giver, receiver, team, pts, rng) {
    const why = Gift.check(giver, receiver, team, pts);
    if (why) return { ok: false, reason: why };
    const cost = Gift.cost(giver, pts);
    let rec;
    if (!receiver.type.canAcceptGifts()) {
      rec = { giver, receiver, pts, cost: 0, status: "refused", refused: true, cancelled: false };
    } else {
      // Collaboration x 10% chance the gift costs 1 heart less. Every gift costs at least 1 heart.
      // Not rolled for refused gifts.
      const discount = giver.rollAbility("collab", rng);
      const paid = discount ? Math.max(Gift.MIN_COST, cost - 1) : cost;
      // .discount is true only when the cost really went down (a 1-heart gift stays 1).
      giver.hearts.spend(paid);
      rec = { giver, receiver, pts, cost: paid, discount: paid < cost, status: "pending", refused: false, cancelled: false };
    }
    round.gifts.push(rec);
    return { ok: true, gift: rec, ...rec };
  }

  /* Accept: points land. Points with nowhere to go are refunded to the giver.
     savesAttendance (true in the gift window): the gift also cancels a pending missed check-in.
     Its points still go to the lowest attribute (or the glitching attribute, if one is below 0).
     Lifeline: only a gift that cancels a glitch counts (Glitching before, not Glitching after). */
  static accept(round, rec, { savesAttendance = false } = {}) {
    if (rec.status !== "pending") return { ok: false, reason: "This gift was already answered." };
    if (rec.receiver.idle) return { ok: false, reason: "You are idle." };
    const { giver, receiver, pts } = rec;
    const wasGlitching = receiver.isGlitchingAny();
    rec.target = receiver.giftTarget();
    rec.overflow = receiver.receiveGift(pts);
    if (rec.overflow) {   // never refund more than the giver paid (a discounted gift paid less)
      giver.hearts.refund(Math.min(rec.cost, rec.overflow * Gift.refundPerPoint(giver)));
    }
    rec.savedAttendance = savesAttendance && receiver.attendancePending;
    if (rec.savedAttendance) receiver.attendancePending = false;
    rec.cancelled = wasGlitching && !receiver.isGlitchingAny();   // only a real rescue counts
    if (rec.cancelled) giver.creditPath(CharacterType.PATH_EVENTS.rescue);   // Lifeline
    rec.status = "accepted";
    return { ok: true, gift: rec, ...rec };
  }

  /* Decline (or "expired" when no one answered): the giver gets the hearts back. */
  static decline(round, rec, status = "declined") {
    if (rec.status !== "pending") return { ok: false, reason: "This gift was already answered." };
    if (status === "declined" && rec.receiver.idle) return { ok: false, reason: "You are idle." };
    rec.giver.hearts.refund(rec.cost);
    rec.status = status;
    return { ok: true, gift: rec, ...rec };
  }

  static pending(round) { return round.gifts.filter(g => g.status === "pending"); }

  /* End of Open Floor or the gift window: unanswered gifts are declined and refunded. */
  static expireAll(round) { return Gift.pending(round).map(g => Gift.decline(round, g, "expired")); }
}

Gift.MIN_COST = 1;   // every gift costs at least 1 heart
return Gift;
})();

/* ---------- rules/Round.js ---------- */
const Round = (() => {
/* Round: one level. Trial attribute, cost, how it is scored, and the step order. */

// Package A order. Trial activities stay in their original levels.
const LEVELS = [
  { n: 1, name: "Boot Up",    trialName: "SOP mini-game",                attr: "grit",       cost: 2, judged: false, trialKind: "sop" },
  { n: 2, name: "Sprint 1",   trialName: "Prioritize against a timer",   attr: "collab",     cost: 3, judged: false, trialKind: "splitBrief" },
  { n: 3, name: "The Mirror", trialName: "Q&A gauntlet",                 attr: "focus",      cost: 3, judged: false, trialKind: "auto" },
  { n: 4, name: "Geek Week",  trialName: "Testing challenge",            attr: "initiative", cost: 4, judged: false, trialKind: "auto" },
  { n: 5, name: "Sprint 2",   trialName: "Fix the broken team",          attr: "composure",  cost: 4, judged: true,  trialKind: "judged" },
  { n: 6, name: "Sprint 3",   trialName: "Final build and dream speech", attr: "composure",  cost: 5, judged: true,  trialKind: "judged" },
  { n: 7, name: "Graduation", trialName: "Crack the simulation",         attr: null,         cost: 0, judged: false, trialKind: null }
];

// Every level opens with a briefing (no player actions). Level 7: briefing, then graduation.
const STEPS = ["briefing", "openFloor", "trial", "glitchReport", "giftWindow", "lockIn", "statsUpdate"];
const FINAL_STEPS = ["briefing", "graduation"];

class Round {
  constructor(levelNumber) {
    const lv = LEVELS[levelNumber - 1];
    if (!lv) throw new Error("No level " + levelNumber);
    Object.assign(this, lv);
    this.isFinal = lv.n === 7;
    this.stepIndex = 0;
    this.trial = null;
    this.sabotages = [];    // { actor, target, drain, cost }
    this.accusations = [];  // { accuser, target, correct }
    this.gifts = [];        // { giver, receiver, pts, cost, refused, cancelled }
    this.completed = new Set();   // one-time Game actions already run this round
    this.sopBoards = {};
    this.sopResults = {};
    this.earnings = {};
    this.quietHearts = [];
    this.gritBonus = [];
    this.done = false;
  }
  static get LEVELS() { return LEVELS; }
  static get STEPS() { return STEPS; }
  get steps() { return this.isFinal ? FINAL_STEPS : STEPS; }
  get step() { return this.steps[this.stepIndex]; }
  nextStep() { if (this.stepIndex < this.steps.length - 1) this.stepIndex += 1; return this.step; }
  saboteurs() { return [...new Set(this.sabotages.map(s => s.actor))]; }
  /* Total drained from this player by sabotage this round. */
  drainOn(p) { return this.sabotages.filter(s => s.target === p).reduce((n, s) => n + s.drain, 0); }
  /* Teammates caught sabotaging this round by a correct accusation (each once), leaving out one player. */
  caughtOn(team, except = null) {
    return [...new Set(this.accusations.filter(a => a.correct && team.has(a.target) && a.target !== except).map(a => a.target))];
  }

  /* Round actions (Step 7): Game checks step order, then calls Round. */
  sabotage(actor, target, team, rng) { return Sabotage.apply(this, actor, target, team, rng); }
  gift(giver, receiver, team, pts, rng) { return Gift.apply(this, giver, receiver, team, pts, rng); }
  answerGift(gift, accept) {
    // Only a gift accepted in the gift window saves a player from a missed check-in.
    return accept ? Gift.accept(this, gift, { savesAttendance: this.step === "giftWindow" })
                  : Gift.decline(this, gift);
  }
  accuse(accuser, target, team, rng) { return Accusation.apply(this, accuser, target, team, rng); }
  endGlitchReport() {
    // Exploit: +1 for each Contrarian who sabotaged this round and was not caught.
    for (const p of this.saboteurs()) if (!p.caughtThisRound) p.creditPath(CharacterType.PATH_EVENTS.uncaughtSabotage);
  }
  closeGlitchReport({ advance, refreshTimer } = {}) {
    this.endGlitchReport();
    if (refreshTimer) refreshTimer();
    if (advance) advance();
  }
  closeGiftWindow({ advance, lockIn, computeEarnings }) {
    advance();
    lockIn();
    advance();
    return computeEarnings();
  }

  /* Save (Part 13): plain data, players by id. The level's fixed data (name, attr, cost...) comes back from LEVELS. */
  toJSON() {
    const id = p => p.id;
    const out = {
      n: this.n, stepIndex: this.stepIndex, completed: [...this.completed],
      sabotages: this.sabotages.map(s => ({ ...s, actor: s.actor.id, target: s.target.id })),
      accusations: this.accusations.map(a => ({ ...a, accuser: a.accuser.id, target: a.target.id })),
      gifts: this.gifts.map(g => ({ ...g, giver: g.giver.id, receiver: g.receiver.id })),
    };
    if (this.trial && typeof this.trial === "object") out.trialState = this.trial.toJSON();
    if (this.quietHearts) out.quietHearts = this.quietHearts.map(id);
    if (this.gritBonus) out.gritBonus = this.gritBonus.map(id);
    for (const k of ["sopBoards", "sopResults", "earnings", "done"]) if (this[k] !== undefined) out[k] = JSON.parse(JSON.stringify(this[k]));
    return out;
  }
  /* Load. trialFromJSON rebuilds the trial (passed in so Round does not need to know the Trial class). */
  static fromJSON(data, { byId, trialFromJSON }) {
    const r = new Round(data.n);
    const P = id => byId.get(id);
    r.stepIndex = data.stepIndex;
    r.completed = new Set(data.completed);
    r.sabotages = data.sabotages.map(s => ({ ...s, actor: P(s.actor), target: P(s.target) }));
    r.accusations = data.accusations.map(a => ({ ...a, accuser: P(a.accuser), target: P(a.target) }));
    r.gifts = data.gifts.map(g => ({ ...g, giver: P(g.giver), receiver: P(g.receiver) }));
    const ts = data.trialState || (data.trial && typeof data.trial === "object" ? data.trial : null);
    if (ts) r.trial = trialFromJSON(ts);
    if (data.quietHearts) r.quietHearts = data.quietHearts.map(P);
    if (data.gritBonus) r.gritBonus = data.gritBonus.map(P);
    for (const k of ["sopBoards", "sopResults", "earnings", "done"]) if (data[k] !== undefined) r[k] = JSON.parse(JSON.stringify(data[k]));
    return r;
  }
}
return Round;
})();

/* ---------- rules/Vote.js ---------- */
const Vote = (() => {
/* Vote: judged trials with no host. Each active player (not Stuck, not idle) ranks top 3 active players from other teams.
   A ballot cast before the voter went idle stays.
   1st = 3, 2nd = 2, 3rd = 1, times the voter's 1 + Initiative / 10. Points go to the ranked players' teams,
   then each team's total is divided by its active players and by the active players not on that team. Top half of teams win
   (rounded up: 5 teams -> 3 win, 7 teams -> 4).
   Ties at the cutoff: more first-place ranks wins. Still tied: random. */
const POINTS = [3, 2, 1];

class Vote {
  /* canBeRanked: optional check. Levels 5-6 pass "has a submission"; without it, anyone not Stuck. */
  constructor(teams, rng = Math.random, canBeRanked = null) {
    this.teams = teams;
    this.rng = rng;
    this.canBeRanked = canBeRanked || (() => true);
    this.ballots = new Map();   // voter -> [p1, p2, p3]
  }

  teamOf(p) { return this.teams.find(t => t.has(p)); }

  /* Players this voter may rank: not themselves, not their own team, not Stuck, not idle, and (Levels 5-6) submitted. */
  choicesFor(voter) {
    return this.teams.filter(t => !t.has(voter)).flatMap(t => t.members).filter(p => p.isActive() && this.canBeRanked(p));
  }

  /* Normally 3. Fewer only if fewer than 3 players can be ranked at all. */
  slotsFor(voter) { return Math.min(3, this.choicesFor(voter).length); }

  check(voter, ranking) {
    if (voter.isStuck()) return "Stuck players do not vote.";
    if (voter.idle) return "You are idle.";
    const n = this.slotsFor(voter);
    if (ranking.length !== n) return "Rank exactly " + n + " players.";
    if (new Set(ranking).size !== n) return "Pick " + n + " different players.";
    for (const p of ranking) {
      if (p === voter) return "You cannot rank yourself.";
      if (p.isStuck()) return "Stuck players cannot be ranked.";
      if (p.idle) return p.name + " is idle and cannot be ranked.";
      if (!this.canBeRanked(p)) return p.name + " has no submission and cannot be ranked.";
      if (this.teamOf(p) === this.teamOf(voter)) return "You cannot rank your own team.";
    }
    return null;
  }

  cast(voter, ranking) {
    const why = this.check(voter, ranking);
    if (why) return { ok: false, reason: why };
    this.ballots.set(voter, ranking);
    return { ok: true };
  }

  /* Returns teams in final order, and sets team.won.
     total = the team's vote points (each voter's points already x Initiative weight).
     score = total / (team's active players x active players who could rank them, i.e. active players not on
     that team). Active = not Stuck and not idle. Teams rank by score, so team size does not
     matter: big teams have more players to rank, small teams have more possible voters. Either count 0 = score 0. */
  tally() {
    const allActive = this.teams.reduce((n, t) => n + t.active().length, 0);
    const score = new Map(this.teams.map(t => {
      const active = t.active().length;
      return [t, { total: 0, active, voters: allActive - active, score: 0, firsts: 0, roll: this.rng() }];
    }));
    for (const [voter, ranking] of this.ballots) {
      const w = voter.voteWeight();   // Initiative: points x (1 + Initiative / 10)
      ranking.forEach((p, i) => {
        const s = score.get(this.teamOf(p));
        s.total += POINTS[i] * w;
        if (i === 0) s.firsts += 1;
      });
    }
    for (const s of score.values()) s.score = s.active && s.voters ? s.total / (s.active * s.voters) : 0;
    const order = [...this.teams].sort((a, b) => {
      const A = score.get(a), B = score.get(b);
      return (B.score - A.score) || (B.firsts - A.firsts) || (A.roll - B.roll);
    });
    const winners = Math.ceil(this.teams.length / 2);
    order.forEach((t, i) => { t.won = i < winners; });
    return order.map(t => ({ team: t, ...score.get(t), won: t.won }));
  }
}
return Vote;
})();

